import csv
import sys


def read_rows(text):
    reader = csv.reader(text.splitlines())
    header = [h.strip() for h in next(reader)]
    return header, [row for row in reader if any(cell.strip() for cell in row)]


def to_number(text, kind):
    return kind(text.replace(",", ""))


def clean(header, rows):
    kept, problems = [], []
    for line_no, row in enumerate(rows, start=2):
        if len(row) != len(header):
            problems.append(f"line {line_no}: expected {len(header)} fields, got {len(row)}")
            continue
        rec = {name: cell.strip() for name, cell in zip(header, row)}
        if not rec["region"]:
            problems.append(f"line {line_no}: missing region")
            continue
        try:
            units = to_number(rec["units"], int)
        except ValueError:
            problems.append(f"line {line_no}: bad units {rec['units']!r}")
            continue
        if units <= 0:
            problems.append(f"line {line_no}: units must be positive")
            continue
        try:
            price = to_number(rec["price"], float)
        except ValueError:
            problems.append(f"line {line_no}: bad price {rec['price']!r}")
            continue
        rec.update(region=rec["region"].title(), units=units, price=price)
        kept.append(rec)
    return kept, problems


def main():
    header, rows = read_rows(sys.stdin.read())
    print(f"Loaded {len(rows)} rows, {len(header)} columns: {', '.join(header)}")
    kept, problems = clean(header, rows)
    print(f"Kept {len(kept)}, rejected {len(problems)}")
    for p in problems:
        print(f"  {p}")


main()
